    /** SAF-T durează minute pe luni mari; restul secunde. Plafon generos, dar finit. */
    private static final long TIMEOUT_MINUTE = 15;

    private ValidatorAnaf() {
    }

    /** Directorul kitului DUK (imaginea îl coace la /opt/idempiere/duk). */
    public static String dukDir() {
        return MSysConfig.getValue("EVA_DUK_DIR", "/opt/idempiere/duk");
    }

    /**
     * Validează XML-ul unei declarații. {@code an}/{@code luna} sunt cerute doar de SAF-T
     * (D406/D406T — kitul cu sintaxă proprie); pentru restul se dau null.
     */
    public static Rezultat valideaza(String tipDeclaratie, Path xml, Integer an, Integer luna)
            throws Exception {
        if (tipDeclaratie != null && tipDeclaratie.startsWith("INS_"))   // T27a S75: Intrastat = schema INS, nu DUK
            return ValidatorIntrastat.valideaza(xml);                      // T27a S75
        return ruleaza(tipDeclaratie, xml, an, luna, null, null);
    }

    /**
     * Validează și produce PDF-ul inteligent cu XML-ul atașat — formatul unic acceptat la
     * depunere (XML „gol" nu se acceptă), inclusiv la SAF-T D406 (T16 B1: {@code -p D406}).
     * Fără ZIP atașat: parametrul {@code fisierZIP=0} (regula #3 din README).
     */
    public static Rezultat pdf(String tipDeclaratie, Path xml, Path pdfOut, Integer an, Integer luna)
            throws Exception {
        return ruleaza(tipDeclaratie, xml, an, luna, pdfOut, null);
    }

    /**
     * Ca {@link #pdf(String, Path, Path, Integer, Integer)}, dar cu ZIP-ul documentelor
     * însoțitoare atașat în PDF-ul inteligent. Bilanțurile (S1002/S1003/S1005) au «Fișier .ZIP
     * OBLIGATORIU în atașament» — fără el DUK dă «Eroare creare PDF: zip obligatoriu dar
     * nespecificat» (declarația rămâne «Validata», nu ajunge «PDF»). {@code zip=null} → fără ZIP
     * (parametrul {@code fisierZIP=0}, comportamentul declarațiilor obișnuite).
     */
    public static Rezultat pdf(String tipDeclaratie, Path xml, Path pdfOut, Integer an, Integer luna,
                               Path zip) throws Exception {
        return ruleaza(tipDeclaratie, xml, an, luna, pdfOut, zip);
    }

    /** Codul kitului DUK al tipului din registru: «D392A» (formularul 392A) → kitul «D392»; altfel neschimbat. Pur. P01.T177 */
    public static String codKit(String tip) {
        return "D392A".equals(tip) ? "D392" : tip;
    }

    private static Rezultat ruleaza(String tip, Path xml, Integer an, Integer luna, Path pdfOut,
                                    Path zip) throws Exception {
        if (!Files.isReadable(xml))
            throw new IOException("Fișierul XML nu există sau nu e lizibil: " + xml);
        File duk = new File(dukDir());
        // SAF-T: jar-ul „AnLunaUI" se BLOCHEAZĂ headless (rămâne în UI/futex — dovedit la
        // prototipare); DUKIntegrator.jar simplu validează D406 corect, doar cere memorie.
        boolean saft = tip != null && tip.toUpperCase().startsWith("D406");
        File jar = new File(duk, "DUKIntegrator.jar");
        if (!jar.isFile())
            throw new IOException("Kitul DUK lipsește: " + jar
                    + " (imaginea trebuie să conțină /opt/idempiere/duk; vezi idempiere/Dockerfile)");

        Path err = xml.resolveSibling(xml.getFileName() + ".err.txt");
        Files.deleteIfExists(err);

        String java = System.getProperty("java.home") + File.separator + "bin"
                + File.separator + "java";
        List<String> cmd = new ArrayList<>();
        cmd.add(java);
        if (saft)
            cmd.add("-Xmx4g");   // sintaxa documentată ANAF pentru D406 (fișiere de sute de MB)
        cmd.add("-jar");
        cmd.add(jar.getAbsolutePath());
        cmd.add(pdfOut == null ? "-v" : "-p");
        cmd.add(codKit(tip));   // P01.T177: D392A (392A) se validează cu kitul D392
        cmd.add(xml.toAbsolutePath().toString());
        cmd.add(err.toAbsolutePath().toString());
        cmd.add("$");            // optiuneValidare: valoarea implicită (regula #2: „$", nu omis)
        if (pdfOut != null) {
            // fisierZIP: 0 = fără atașament (regula #3); altfel calea ZIP-ului documentelor
            // însoțitoare (obligatoriu la bilanțuri).
            if (zip != null && Files.isReadable(zip))
                cmd.add(zip.toAbsolutePath().toString());
            else
                cmd.add("0");
            cmd.add(pdfOut.toAbsolutePath().toString());
        }

        ProcessBuilder pb = new ProcessBuilder(cmd);
        pb.directory(duk);
        pb.redirectErrorStream(true);
        Process p = pb.start();
        String consola = new String(p.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        if (!p.waitFor(TIMEOUT_MINUTE, TimeUnit.MINUTES)) {
            p.destroyForcibly();
            throw new IOException("DUKIntegrator nu a terminat în " + TIMEOUT_MINUTE
                    + " minute (" + tip + ", " + xml.getFileName() + ")");
        }
        // codul de ieșire NU se consultă (mereu 0) — doar fișierul de erori decide.

        String text = Files.isReadable(err)
                ? Files.readString(err, StandardCharsets.UTF_8)
                : "";
        if (text.isBlank())
            // fără fișier de erori = kit stricat / tip necunoscut; consola conține mesajul real
            return new Rezultat(false, List.of("F: DUKIntegrator nu a produs fișierul de erori"),
                    List.of(), consola, null);

        boolean explicitOk = text.strip().equals("ok") || text.strip().startsWith("ok");
        List<String> erori = new ArrayList<>();
        List<String> avert = new ArrayList<>();
        for (String linie : text.split("\\R")) {
            String l = linie.strip();
            if (l.startsWith("E:") || l.startsWith("F:"))
                erori.add(l);
            // W: avertisment ȘI A: atenționare/notificare — AMBELE sunt NEblocante (DUK produce
            // oricum PDF-ul, declarația se poate depune). Bug reparat: A: nu era clasificat
            // nicăieri, iar cum textul nu începe cu «ok», declarația cu DOAR atenționări (ex.
            // D394 R232.3 «baza*cota/100 - tva > 5 RON») rămânea ok=false → stare «Eroare»,
            // deși ANAF o acceptă. (E:/F: rămân singurele blocante.)
            else if (l.startsWith("W:") || l.startsWith("A:"))
                avert.add(l);
        }
        // valid = fără erori/fatale; «ok» explicit SAU măcar linii recunoscute (atenționări/
        // avertismente) — un fișier nerecunoscut, fără nimic, rămâne neok (plasă de siguranță)
        boolean ok = erori.isEmpty() && (explicitOk || !avert.isEmpty());
        String pdfProdus = null;
        if (pdfOut != null && ok) {
            if (Files.isReadable(pdfOut) && pdfOut.toFile().length() > 0)
                pdfProdus = pdfOut.toString();
            else {
                ok = false;
                erori.add("E: validarea a trecut dar PDF-ul nu a fost produs (vezi consola)");
                text = text + "\n" + consola;
            }
        }
        return new Rezultat(ok, erori, avert, text, pdfProdus);
    }
