    /** Regula PURĂ a dreptului: procesul există și rolul are acces citire-scriere ({@code getProcessAccess} = TRUE). */
    public static boolean drept(int proces, Boolean acces) {
        return proces > 0 && Boolean.TRUE.equals(acces);
    }

    /**
     * Dreptul rolului sesiunii pe procesul {@link #VALUE} (D-05a-1 varianta b), O SINGURĂ funcție chemată de buton și de proces
     * (X207 / M-15); rolul prin {@code MRole.get} (X268).
     */
    public static boolean areDrept(Properties ctx) {
        Surse s = surse();
        int proces = s.procesId();
        return drept(proces, proces > 0 ? s.acces(ctx, proces) : null);
    }

    /** PUR: k din parametrul {@code Qty}: întreg ⇒ valoarea (≤ 0 refuzat de {@code refuzCerere}); fracția, null sau în afara {@code int} ⇒ 0 (N-10 «1,5»). */
    public static int cantitate(BigDecimal q) {
        if (q == null)
            return 0;
        BigDecimal n = q.stripTrailingZeros();
        if (n.scale() > 0 || n.compareTo(BigDecimal.valueOf(Integer.MAX_VALUE)) > 0 || n.compareTo(BigDecimal.valueOf(Integer.MIN_VALUE)) < 0)
            return 0;
        return n.intValueExact();
    }

    /** PUR: tipul notei din parametrul {@link #P_TIP}; altă valoare ⇒ {@code null} (refuzat de {@code refuzCerere}). */
    public static NotaSetWms.Tip tip(int v) {
        return v == TIP_AMBALARE ? NotaSetWms.Tip.AMBALARE : v == TIP_DEZAMBALARE ? NotaSetWms.Tip.DEZAMBALARE : null;
    }

    @Override
    protected void prepare() {
        for (ProcessInfoParameter p : getParameter()) {
            String n = p.getParameterName();
            if (P_GESTIUNE.equals(n))
                gestiune = p.getParameterAsInt();
            else if (P_TIP.equals(n))
                tipNota = p.getParameterAsInt();
            else if (P_SET.equals(n))
                set = p.getParameterAsInt();
            else if (P_CANTITATE.equals(n))
                k = cantitate(p.getParameterAsBigDecimal());
            else if (P_POZITIE.equals(n))
                locator = p.getParameterAsInt();
            else if (P_VERSIUNE.equals(n))
                bom = p.getParameterAsInt();
        }
    }

    private static AdempiereException refuz(String cheie, Object... arg) {
        return new AdempiereException(Etichete.t(cheie, arg));
    }

    /** Rezultatul calculului: perechea citită și mișcările notei (încă nescrise). */
    record Plan(PerecheWms pereche, List<MiscareWms> miscari) {
    }

    /**
     * P01.T355 D-11a-1 (amendamentul {@code 11a_}, contractul lotului B): mișcările notei FĂRĂ scriere — pașii (ii)–(viii) din
     * {@code doIt} (firma, perechea, cererea, definiția, piesele, alocarea pe poziții), fără lacăt și fără {@code StocWms.inregistreaza},
     * pe tranzacția {@code null} (previzualizarea dialogului). {@code tip} = {@link #TIP_AMBALARE} / {@link #TIP_DEZAMBALARE}; un refuz ⇒
     * {@link AdempiereException} cu textul tradus (același ca la «Înregistrez»). Rândurile au {@code AD_Table_ID} = {@code AD_PInstance}
     * și {@code Record_ID} = 0 (instanța nu există încă). {@code doIt} folosește același drum ({@link #planeaza}).
     */
    public static List<MiscareWms> plan(Properties ctx, int g, int tip, int set, int k, int locator, int bom) {
        Surse s = surse();
        return planeaza(s, ctx, g, tip, set, k, locator, bom, s.tabelaInstanta(), 0, null).miscari();
    }

    /** Drumul unic de calcul al notei ({@link #plan} și {@code doIt}), pe tranzacția dată; nu ia lacăte și nu scrie. */
    static Plan planeaza(Surse s, Properties ctx, int g, int tipNota, int set, int k, int locator, int bom, int tabela, int record,
            String trx) {
        int client = Env.getAD_Client_ID(ctx);
        if (client <= 0)                                                                         // (ii)
            throw refuz(NotaSetWms.R_FIRMA);
        PerecheWms p = s.pereche(client, g, trx);
        if (p == null)                                                                           // (iii)
            throw refuz(R_FARA_PERECHE);
        int w = p.gestiuneWms();
        NotaSetWms.Tip t = tip(tipNota);
        boolean dez = t == NotaSetWms.Tip.DEZAMBALARE;
        Set<Integer> locW = s.locatori(client, w, trx);
        String r = NotaSetWms.refuzCerere(new NotaSetWms.Cerere(t, client, w, p.locatorExpediere(), set, k, locator, dez ? bom : 0,
                tabela, record), locW);
        if (r != null)
            throw refuz(r);
        Object[] pr = s.produs(client, set, trx);                                               // (v) definiția
        boolean isBom = pr != null && Boolean.TRUE.equals(pr[0]), isStocked = pr != null && Boolean.TRUE.equals(pr[1]);
        String tipProdus = pr == null ? null : (String) pr[2];
        int versiune, liste;
        List<SetLista.RandLista> randuri;
        if (dez) {
            versiune = bom;
            r = NotaSetWms.refuzSet(s.cantitateSet(client, locator, set, versiune, trx), k);  // citit FĂRĂ blocare (§3.9)
            if (r != null)
                throw refuz(r);
            liste = 1;   // versiunea rândului poate fi o listă veche (N-4): fără condiția «o singură listă»
            randuri = s.randuri(client, versiune, trx);
        } else {
            List<Integer> l = s.liste(client, set, trx);
            liste = l.size();
            versiune = liste == 1 ? l.get(0) : 0;
            randuri = liste == 1 ? s.randuri(client, versiune, trx) : List.of();
        }
        r = NotaSetWms.refuzDefinitie(isBom, isStocked, tipProdus, liste, randuri, versiune > 0 ? s.cuLot(client, versiune, trx) : 0);
        if (r != null)                                                                           // (vi)
            throw refuz(R_DEFINITIE, Etichete.t(r));
        NotaSetWms.Cerere c = new NotaSetWms.Cerere(t, client, w, p.locatorExpediere(), set, k, locator, versiune, tabela, record);
        Map<Integer, BigDecimal> bucati = s.piese(client, set, versiune, trx);                  // (vii)
        if (bucati == null || bucati.isEmpty())
            throw refuz(R_DEFINITIE, Etichete.t(SetLista.M_FARA_LINII));
        if (dez)
            return new Plan(p, NotaSetWms.dezambalare(c, bucati));
        Map<Integer, BigDecimal> necesar = new TreeMap<>(), disp = new LinkedHashMap<>();       // (viii)
        Map<Integer, Map<Integer, BigDecimal>> stoc = new LinkedHashMap<>();
        for (Map.Entry<Integer, BigDecimal> e : new TreeMap<>(bucati).entrySet()) {
            Map<Integer, BigDecimal> poz = s.pePozitii(client, w, e.getKey(), trx);
            Map<Integer, BigDecimal> alocabil = NotaSetWms.faraExpediere(poz, p.locatorExpediere());   // D-11c-2: o singură mulțime
            stoc.put(e.getKey(), alocabil);
            necesar.put(e.getKey(), e.getValue().multiply(BigDecimal.valueOf(k)));
            disp.put(e.getKey(), NotaSetWms.disponibil(alocabil));
        }
        String lipsa = NotaSetWms.lipsa(necesar, disp, x -> s.codProdus(x, trx));
        if (lipsa != null)
            throw new AdempiereException(lipsa);
        Map<Integer, Integer> prioritate = s.prioritate(client, w, trx);
        AlegerePozitii.Ordine ordine = s.ordine(client, trx);
        Map<Integer, List<AlegerePozitii.Alocare>> alocari = new LinkedHashMap<>();
        for (Map.Entry<Integer, BigDecimal> e : necesar.entrySet())
            alocari.put(e.getKey(), NotaSetWms.alocaPiese(stoc.get(e.getKey()), prioritate, e.getValue(), ordine));
        return new Plan(p, NotaSetWms.ambalare(c, bucati, alocari));
    }

    @Override
    protected String doIt() throws Exception {
        Surse s = surse();
        Properties ctx = getCtx();
        String trx = get_TrxName();
        if (!areDrept(ctx))                                                                     // (i)
            throw refuz(R_DREPT);
        int client = Env.getAD_Client_ID(ctx);
        if (client <= 0)                                                                         // (ii)
            throw refuz(NotaSetWms.R_FIRMA);
        PerecheWms p = s.pereche(client, gestiune, trx);
        if (p == null)                                                                           // (iii)
            throw refuz(R_FARA_PERECHE);
        s.lacat(NotaSetWms.cheieLacat(client, p.gestiuneWms()), trx);                            // (iv) înaintea citirilor
        Plan pl = planeaza(s, ctx, gestiune, tipNota, set, k, locator, bom, s.tabelaInstanta(), getAD_PInstance_ID(), trx);   // recitit sub lacăt
        s.inregistreaza(ctx, client, pl.miscari(), trx);                                         // (ix) o singură dată
        return Etichete.t(K_GATA, Etichete.t(tip(tipNota) == NotaSetWms.Tip.DEZAMBALARE ? "t355.ui.dezambalare" : "t355.ui.ambalare"), k,
                s.codProdus(set, trx), s.codLocator(locator, trx), pl.miscari().size());
    }

